<?php require_once __DIR__.'/api/auth_common.php';requireAdmin(false); ?>
<!doctype html><html lang="es"><meta charset="utf-8"><title>Datos demo · Crimson</title><style>body{font:15px Ubuntu,Arial;background:#f5f5f5;margin:0;color:#222}header{background:crimson;color:white;padding:17px;display:flex;justify-content:space-between}header a{color:white}main{max-width:1000px;margin:25px auto;background:white;padding:25px;border:1px solid #ddd}label{display:block;margin:12px 0}button{background:crimson;color:white;border:0;padding:11px 18px;cursor:pointer}button:disabled{opacity:.5}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:8px}.grid label{border:1px solid #ddd;padding:10px;margin:0}pre{background:#f6f6f6;padding:18px;white-space:pre-wrap}select,input{padding:7px}</style><header><b>jocarsa | crimson · Generador de datos</b><a href="configuracion.php">Volver a configuración</a></header><main><h1>Datos de demostración</h1><p>Generación mediante JocarsaBBDD, respetando las claves foráneas. No modifica las tablas internas.</p><div id="tables" class="grid">Cargando…</div><label>Registros por tabla <select id="count"><option>10</option><option selected>100</option><option>500</option><option>1000</option></select></label><label>Modo <select id="mode"><option value="empty">Solo tablas vacías</option><option value="append">Añadir a los existentes</option></select></label><button id="preview">Simular</button> <button id="generate">Generar datos</button><pre id="output">Selecciona las tablas y pulsa Simular.</pre></main><script>
async function call(action,body){let r=await fetch('api/demo.php?action='+action,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):null});let d=await r.json();if(!d.ok)throw Error(d.error);return d}
(async()=>{try{let d=await call('schema');tables.replaceChildren();d.tables.forEach(t=>{let l=document.createElement('label'),c=document.createElement('input');c.type='checkbox';c.value=t.name;c.checked=true;l.append(c,document.createTextNode(' '+t.name+' ('+t.count+' registros)'));tables.append(l)})}catch(e){output.textContent=e.message}})();
async function run(sim){let chosen=[...tables.querySelectorAll('input:checked')].map(x=>x.value);if(!chosen.length)return alert('Selecciona al menos una tabla');if(!sim&&!confirm('Se insertarán datos en JocarsaBBDD. ¿Continuar?'))return;preview.disabled=generate.disabled=true;output.textContent='Procesando…';try{let d=await call('generate',{tables:chosen,count:Number(count.value),mode:mode.value,preview:sim});output.textContent=(sim?'SIMULACIÓN':'INSERCIÓN')+'\n'+d.results.map(x=>x.table+': '+x.inserted+' · '+x.reason).join('\n')}catch(e){output.textContent='Error: '+e.message}finally{preview.disabled=generate.disabled=false}}
preview.onclick=()=>run(true);generate.onclick=()=>run(false);
</script></html>